import { internationalization } from '@intlayer/config/built';
import type { LocalesValues } from '@intlayer/types/module_augmentation';
import { getCachedIntl } from '../utils/intl';

/**
 * Formats a number as a percentage string (e.g., 0.25 → "25%").
 *
 * @example
 * percentage(0.25); // "25%"
 *
 * @example
 * percentage(0.25, { minimumFractionDigits: 2 }); // "25.00%"
 */
export const percentage = (
  value: string | number,
  {
    locale,
    ...options
  }: Intl.NumberFormatOptions & { locale?: LocalesValues } = {}
): string => {
  let numericValue = Number(value);

  // Normalize: if user passes 10, treat it as 10% instead of 1000%
  if (numericValue > 1) {
    numericValue /= 100;
  }

  const formatter = getCachedIntl(
    'NumberFormat',
    locale ?? internationalization?.defaultLocale,

    {
      style: 'percent',
      ...options,
    }
  );

  return formatter.format(Number(numericValue));
};
